import { isWon, MOVES_MAX, ELAPSED_MAX_MS } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import { decodeSnapshot } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { matchSpecs } from './bracket.ts';
import { acceptedNames, normalizePlayerName } from './model.ts';
import type {
  TournamentMatch,
  TournamentPlayer,
  TournamentRecord,
  TournamentResult,
  TournamentRound,
  TournamentState,
} from './model.ts';
import { compareTournamentResults } from './rules.ts';

const RECORD_KEYS = ['championSeed', 'currentMatch', 'currentTurn', 'matches', 'players', 'status'];
const STATE_KEYS = ['activeGame', ...RECORD_KEYS];
const MATCH_KEYS = [
  'boardCode', 'feeders', 'matchNumber', 'playerSeeds', 'results', 'round', 'size', 'winnerSeed',
];

export function readTournamentRecord(value: unknown): TournamentRecord | null {
  if (!isJsonObject(value) || !hasExactKeys(value, RECORD_KEYS) || value.status !== 'finished')
    return null;
  const state = readTournamentFields(value, null);
  if (!state || state.status !== 'finished' || state.championSeed === null) return null;
  const { status, players, matches, currentMatch, currentTurn, championSeed } = state;
  return { status, players, matches, currentMatch, currentTurn, championSeed };
}

export function readTournamentState(value: unknown): TournamentState | null {
  if (!isJsonObject(value) || !hasExactKeys(value, STATE_KEYS)) return null;
  const gameText = value.activeGame;
  if (gameText !== null && typeof gameText !== 'string') return null;
  const game = typeof gameText === 'string' ? decodeSnapshot(gameText) : null;
  if (typeof gameText === 'string' && !game) return null;
  const state = readTournamentFields(value, game);
  if (!state || !validActiveGame(state)) return null;
  return state;
}

function readTournamentFields(
  value: Record<string, unknown>,
  game: TournamentState['activeGame'],
): TournamentState | null {
  if (
    !isNonnegativeSafeInteger(value.currentMatch) ||
    !isNonnegativeSafeInteger(value.currentTurn) ||
    (value.currentTurn !== 0 && value.currentTurn !== 1) ||
    (value.status !== 'active' && value.status !== 'finished') ||
    !(value.championSeed === null || isNonnegativeSafeInteger(value.championSeed))
  ) return null;
  const players = readPlayers(value.players);
  if (!players) return null;
  const matches = readMatches(value.matches, players.length);
  if (!matches || !validProgress(players.length, matches, value.currentMatch, value.currentTurn, value.status, value.championSeed))
    return null;
  return {
    status: value.status,
    players,
    matches,
    currentMatch: value.currentMatch,
    currentTurn: value.currentTurn,
    activeGame: game,
    turnRunning: false,
    championSeed: value.championSeed,
  };
}

function readPlayers(value: unknown): TournamentPlayer[] | null {
  if (!Array.isArray(value) || (value.length !== 4 && value.length !== 8)) return null;
  const players: TournamentPlayer[] = [];
  for (let index = 0; index < value.length; index += 1) {
    const item: unknown = value[index];
    if (!isJsonObject(item) || !hasExactKeys(item, ['name', 'seed'])) return null;
    if (typeof item.name !== 'string' || item.seed !== index + 1) return null;
    const name = normalizePlayerName(item.name);
    if (name !== item.name || !acceptedNames([name], 1)) return null;
    players.push({ name, seed: item.seed });
  }
  return acceptedNames(players.map((player) => player.name), players.length) ? players : null;
}

function readMatches(value: unknown, playerCount: number): TournamentMatch[] | null {
  const specs = matchSpecs(playerCount);
  if (!Array.isArray(value) || value.length !== specs.length) return null;
  const matches: TournamentMatch[] = [];
  const codes = new Set<string>();
  for (let index = 0; index < value.length; index += 1) {
    const item: unknown = value[index];
    const spec = specs[index];
    if (!spec || !isJsonObject(item) || !hasExactKeys(item, MATCH_KEYS)) return null;
    if (
      typeof item.boardCode !== 'string' ||
      parseBoardCode(item.boardCode)?.size !== spec.size ||
      codes.has(item.boardCode) ||
      !isRound(item.round) || item.round !== spec.round ||
      item.matchNumber !== spec.matchNumber ||
      item.size !== spec.size
    ) return null;
    const playerSeeds = readSeeds(item.playerSeeds, playerCount);
    const feeders = readFeeders(item.feeders, specs.length);
    const results = readResults(item.results, playerSeeds, spec.size);
    if (!playerSeeds || !sameFeeders(feeders, spec.feeders) || !results) return null;
    if (!(item.winnerSeed === null || isNonnegativeSafeInteger(item.winnerSeed))) return null;
    const winner = results[0] && results[1] ? compareTournamentResults(results[0], results[1]) : null;
    if (item.winnerSeed !== winner) return null;
    codes.add(item.boardCode);
    matches.push({
      boardCode: item.boardCode,
      feeders,
      matchNumber: spec.matchNumber,
      playerSeeds,
      results,
      round: spec.round,
      size: spec.size,
      winnerSeed: winner,
    });
  }
  return matches;
}

function readSeeds(value: unknown, count: number): readonly [number | null, number | null] | null {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const first = value[0];
  const second = value[1];
  const valid = (seed: unknown): seed is number | null =>
    seed === null || (isNonnegativeSafeInteger(seed) && seed > 0 && seed <= count);
  return valid(first) && valid(second) ? [first, second] : null;
}

function readFeeders(value: unknown, count: number): readonly [number, number] | null | false {
  if (value === null) return null;
  if (!Array.isArray(value) || value.length !== 2) return false;
  const [first, second] = value;
  if (!isNonnegativeSafeInteger(first) || !isNonnegativeSafeInteger(second)) return false;
  if (first >= count || second >= count || first === second) return false;
  return [first, second];
}

function sameFeeders(
  actual: readonly [number, number] | null | false,
  expected: readonly [number, number] | null,
): actual is readonly [number, number] | null {
  return actual !== false &&
    (actual === null ? expected === null : expected !== null && actual[0] === expected[0] && actual[1] === expected[1]);
}

function readResults(
  value: unknown,
  seeds: readonly [number | null, number | null] | null,
  size: number,
): readonly [TournamentResult | null, TournamentResult | null] | null {
  if (!seeds || !Array.isArray(value) || value.length !== 2) return null;
  const first = readResult(value[0], seeds[0], size);
  const second = readResult(value[1], seeds[1], size);
  if (first === false || second === false) return null;
  return [first, second];
}

function readResult(value: unknown, seed: number | null, size: number): TournamentResult | null | false {
  if (value === null) return null;
  if (!isJsonObject(value) || !hasExactKeys(value, ['elapsedMs', 'moves', 'seed'])) return false;
  if (
    seed === null || value.seed !== seed ||
    !isNonnegativeSafeInteger(value.moves) || value.moves > MOVES_MAX || value.moves < size ** 2 / 2 ||
    typeof value.elapsedMs !== 'number' || !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 || value.elapsedMs > ELAPSED_MAX_MS
  ) return false;
  return { elapsedMs: value.elapsedMs, moves: value.moves, seed };
}

function validProgress(
  count: number,
  matches: readonly TournamentMatch[],
  current: number,
  turn: number,
  status: unknown,
  champion: unknown,
): boolean {
  if (current >= matches.length) return false;
  const specs = matchSpecs(count);
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const spec = specs[index];
    if (!match || !spec) return false;
    if (index < current && match.winnerSeed === null) return false;
    if (index > current && (match.winnerSeed !== null || match.results[0] || match.results[1])) return false;
    if (!spec.feeders) {
      if (match.playerSeeds[0] !== spec.playerSeeds[0] || match.playerSeeds[1] !== spec.playerSeeds[1]) return false;
    } else if (index <= current) {
      const first = matches[spec.feeders[0]]?.winnerSeed;
      const second = matches[spec.feeders[1]]?.winnerSeed;
      if (first === null || first === undefined || second === null || second === undefined) return false;
      if (match.playerSeeds[0] !== first || match.playerSeeds[1] !== second) return false;
    } else if (match.playerSeeds[0] !== null || match.playerSeeds[1] !== null) return false;
  }
  const activeMatch = matches[current];
  if (!activeMatch || (turn === 1 && !activeMatch.results[0]) || (turn === 0 && activeMatch.results[1]))
    return false;
  if (status === 'finished') {
    return current === matches.length - 1 && matches.every((match) => match.winnerSeed !== null) &&
      champion === matches.at(-1)?.winnerSeed;
  }
  return champion === null && !(current === matches.length - 1 && activeMatch.winnerSeed !== null);
}

function validActiveGame(state: TournamentState): boolean {
  const game = state.activeGame;
  if (!game) return true;
  const match = state.matches[state.currentMatch];
  return state.status === 'active' && match?.boardCode === game.boardCode &&
    !match.results[state.currentTurn] && !isWon(game);
}

function isRound(value: unknown): value is TournamentRound {
  return value === 'Quarterfinal' || value === 'Semifinal' || value === 'Final';
}

