    count === 4 ? [[1, 4], [2, 3]] : [[1, 8], [4, 5], [3, 6], [2, 7]];
  const round: TournamentRound = count === 4 ? 'Semifinal' : 'Quarterfinal';
  const specs: MatchSpec[] = opening.map((pair, index) => ({
    round,
    matchNumber: index + 1,
    size: 4,
    playerSeeds: pair,
    feeders: null,
  }));
  if (count === 4) {
    specs.push({ round: 'Final', matchNumber: 1, size: 8, playerSeeds: [null, null], feeders: [0, 1] });
