import { useEffect, useRef, useState } from 'react';
import { Board } from './board/Board.tsx';
import { Controls } from './controls/Controls.tsx';
import { Reproduction } from './controls/Reproduction.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { useGame } from './session/use-game.ts';
import { Tournament } from './tournament/Tournament.tsx';
import './game.css';

export function Game() {
  const [tournamentMode, setTournamentMode] = useState(false);
  const controller = useGame(!tournamentMode);
  const { session } = controller;
  const { game } = session;
  const board = useRef<BoardFocus>(null);
  const tournamentButton = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  useEffect(() => {
    if (!tournamentMode && restoreFocus.current) {
      tournamentButton.current?.focus();
      restoreFocus.current = false;
    }
  }, [tournamentMode]);
  function openTournament(): void {
    controller.suspendForOtherScreen();
    setTournamentMode(true);
  }
  function backToGame(): void {
    controller.resumeFromOtherScreen();
    restoreFocus.current = true;
    setTournamentMode(false);
  }
  function resume(): void {
    board.current?.focusRemembered();
    controller.resume();
  }
  return (
    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <section hidden={tournamentMode}>
        <p className="intro">Reveal two cards. Match their shape and marker to keep the pair.</p>
        <Controls
          size={game.size}
          newGame={controller.newGame}
          restart={controller.restart}
          openTournament={openTournament}
          tournamentButton={tournamentButton}
        />
        <GameStatus
          game={game}
          best={session.preferences.bestMoves[String(game.size)]}
          celebration={session.celebration}
        />
        <p id="board-help" className="help">
          Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
          reveals a card.
        </p>
        <div className="game-result">
          <p role="status" aria-live="polite" aria-atomic="true">
            <span key={session.announcement}>{session.feedback}</span>
          </p>
        </div>
        <Board key={session.generation} game={game} activate={controller.activate} ref={board} />
        <Reproduction
          game={game}
          generation={session.generation}
          exportSnapshot={controller.exportSnapshot}
          loadBoard={controller.loadBoard}
          loadSnapshot={controller.loadSnapshot}
          notice={session.loadNotice}
          paused={session.paused}
          resume={resume}
        />
      </section>
      {tournamentMode && <Tournament backToGame={backToGame} />}
    </main>
  );
}
import { useRef, useState } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { browserStore } from '../session/use-saved-preferences.ts';
import { useTournamentClock } from '../session/use-tournament-clock.ts';
import { matchSpecs } from './bracket.ts';
import { decodeTournament, encodeTournament, encodeTournamentSetup } from './format.ts';
import { acceptedNames, recordOf } from './model.ts';
import type { TournamentImport, TournamentRecord, TournamentState } from './model.ts';
import { createTournament, activateTournamentCard, nextMatch, nextTurn, startTurn } from './rules.ts';
import { readTournamentHistory, saveTournamentHistory } from './storage.ts';
import { findUnknownTournamentField } from './validation.ts';

export function useTournament() {
  const [store] = useState(browserStore);
  const [initial] = useState(() => readTournamentHistory(store));
  const [history, setHistory] = useState<readonly TournamentRecord[]>(initial.records);
  const historyRef = useRef(initial.records);
  const [storageAvailable, setStorageAvailable] = useState(initial.available);
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const current = useRef<TournamentState | null>(null);
  const [notice, setNotice] = useState('');
  const [feedback, setFeedback] = useState('');
  const [announcement, setAnnouncement] = useState(0);
  const clock = useTournamentClock(tournament, current, commit);

  function archive(record: TournamentRecord): void {
    const saved = saveTournamentHistory(store, record, historyRef.current);
    historyRef.current = saved.records;
    setHistory(saved.records);
    setStorageAvailable(saved.available);
  }

  function commit(next: TournamentState | null, saveFinished = true): void {
    const previous = current.current;
    if (next === previous) return;
    current.current = next;
    setTournament(next);
    if (saveFinished && next?.championSeed !== null && next?.championSeed !== undefined && previous?.championSeed === null) {
      const record = recordOf(next);
      if (record) archive(record);
    }
  }

  function begin(names: readonly string[]): boolean {
    const players = acceptedNames(names, names.length);
    if (!players || (players.length !== 4 && players.length !== 8)) return false;
    const specs = matchSpecs(players.length);
    const used = new Set<string>();
    const codes = specs.map((spec) => {
      let code = freshBoardCode(spec.size);
      while (used.has(code)) code = freshBoardCode(spec.size);
      used.add(code);
      return code;
    });
    clock.reset();
    setNotice('');
    setFeedback('');
    commit(createTournament(players, specs, codes));
    return true;
  }

  function beginTurn(): void {
    clock.reset();
    setFeedback('');
    const latest = current.current;
    if (latest) commit(startTurn(latest));
  }

  function activate(index: number): void {
    clock.synchronize();
    const latest = current.current;
    if (!latest) return;
    const next = activateTournamentCard(latest, index);
    const game = next.activeGame;
    if (next !== latest && game && game.selection.kind !== SelectionKind.one) {
      const result = isWon(game)
        ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
        : game.selection.kind === SelectionKind.mismatch
          ? 'No match. Cards close after a short pause.'
          : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
      setFeedback(result);
      setAnnouncement((value) => value + 1);
    }
    commit(next);
  }

  function continueTurn(): void {
    clock.reset();
    setFeedback('');
    const latest = current.current;
    if (latest) commit(nextTurn(latest));
  }

  function continueMatch(): void {
    clock.reset();
    setFeedback('');
    const latest = current.current;
    if (latest) commit(nextMatch(latest));
  }

  function load(text: string): TournamentImport | null {
    const loaded = decodeTournament(text);
    if (!loaded) {
      const field = findUnknownTournamentField(text);
      setNotice(field ? `Unknown field: ${field}.` : 'Invalid tournament.');
      return null;
    }
    clock.reset();
    setFeedback('');
    if (loaded.kind === 'setup') {
      setNotice('Loaded tournament setup.');
      commit(null);
    } else {
      setNotice('Loaded tournament.');
      commit(loaded.state, false);
      const record = recordOf(loaded.state);
      if (record) archive(record);
    }
    return loaded;
  }

  function exportCurrent(count: number, names: readonly string[]): string {
    clock.synchronize();
    const source = current.current ?? historyRef.current[0];
    return source ? encodeTournament(source) : encodeTournamentSetup(count, names);
  }

  function viewPast(record: TournamentRecord): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    commit({ ...record, activeGame: null, turnRunning: false }, false);
  }

  function discard(): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    commit(null);
  }

  return {
    tournament,
    history,
    notice,
    feedback,
    announcement,
    storageAvailable,
    begin,
    beginTurn,
    activate,
    continueTurn,
    continueMatch,
    load,
    exportCurrent,
    viewPast,
    discard,
  };
}
import { useEffect, useRef, useState } from 'react';
import { TournamentHistory } from './TournamentHistory.tsx';
import { TournamentPlay } from './TournamentPlay.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { TournamentTools } from './TournamentTools.tsx';
import { useTournament } from './use-tournament.ts';
import './tournament.css';

interface TournamentProps {
  backToGame(): void;
}

export function Tournament({ backToGame }: TournamentProps) {
  const controller = useTournament();
  const [count, setCount] = useState(4);
  const [names, setNames] = useState<string[]>(Array.from({ length: 8 }, () => ''));
  const [json, setJson] = useState('');
  const heading = useRef<HTMLHeadingElement>(null);
  useEffect(() => heading.current?.focus(), []);

  function updateName(index: number, name: string): void {
    setNames((previous) => previous.map((value, item) => item === index ? name : value));
  }

  function leave(): void {
    controller.discard();
    backToGame();
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={heading} tabIndex={-1}>Tournament</h2>
      <p className="intro">Take turns on the same deal. The player with fewer moves advances.</p>
      {controller.tournament ? (
        <TournamentPlay
          tournament={controller.tournament}
          feedback={controller.feedback}
          announcement={controller.announcement}
          activate={controller.activate}
          startTurn={controller.beginTurn}
          nextTurn={controller.continueTurn}
          nextMatch={controller.continueMatch}
          leave={leave}
          backToGame={backToGame}
        />
      ) : (
        <TournamentSetup
          count={count}
          names={names}
          onCount={setCount}
          onName={updateName}
          onStart={controller.begin}
          backToGame={backToGame}
        />
      )}
      <TournamentTools
        json={json}
        notice={controller.notice}
        onJson={setJson}
        onExport={() => setJson(controller.exportCurrent(count, names))}
        onLoad={() => {
          const loaded = controller.load(json);
          if (loaded?.kind === 'setup') {
            setCount(loaded.count);
            setNames([...loaded.names]);
          }
        }}
      />
      <TournamentHistory
        records={controller.history}
        storageAvailable={controller.storageAvailable}
        onView={controller.viewPast}
      />
    </section>
  );
}
import { useEffect, useRef } from 'react';
import { Board } from '../board/Board.tsx';
