import './tournament.css';

interface TournamentPlayProps {
  tournament: TournamentState;
  feedback: string;
  announcement: number;
  activate(index: number): void;
  startTurn(): void;
  nextTurn(): void;
  nextMatch(): void;
  leave(): void;
  backToGame(): void;
}

export function TournamentPlay(props: TournamentPlayProps) {
  const { tournament } = props;
  const match = tournament.matches[tournament.currentMatch];
  const game = tournament.activeGame;
  const currentResult = match?.results[tournament.currentTurn] ?? null;
  const player = playerName(tournament, match?.playerSeeds[tournament.currentTurn] ?? null);
  const board = useRef<BoardFocus>(null);
  const startButton = useRef<HTMLButtonElement>(null);
  const nextButton = useRef<HTMLButtonElement>(null);
  const backButton = useRef<HTMLButtonElement>(null);
  const hasGame = game !== null;

  useEffect(() => {
    if (tournament.status === 'finished') backButton.current?.focus();
    else if (currentResult) nextButton.current?.focus();
    else if (tournament.turnRunning && hasGame) board.current?.focusRemembered();
    else startButton.current?.focus();
  }, [tournament.currentMatch, tournament.currentTurn, tournament.turnRunning, hasGame, currentResult, tournament.status]);

  if (!match) return null;
  const canAdvanceMatch = tournament.currentMatch < tournament.matches.length - 1;
  const champion = playerName(tournament, tournament.championSeed);
  return (
    <section className="tournament-play" aria-labelledby="tournament-play-heading">
      <h3 id="tournament-play-heading">Tournament bracket</h3>
      {tournament.status === 'active' && (
        <p className="tournament-turn" role="status" aria-live="polite" aria-atomic="true">
          Round: {match.round}<br />Now playing: {player}
        </p>
      )}
      {tournament.status === 'finished' && (
        <p className="tournament-champion" role="status" aria-live="polite">
          Champion: {champion}
        </p>
      )}
      {game && <GameStatistics game={game} />}
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={props.announcement}>{props.feedback}</span>
        </p>
      </div>
      {game && (tournament.turnRunning || isWon(game)) && (
        <>
          <p id="tournament-board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board
            key={`${tournament.currentMatch}-${tournament.currentTurn}`}
            ref={board}
            game={game}
            activate={props.activate}
            helpId="tournament-board-help"
            regionLabel="Tournament game board"
          />
        </>
      )}
      <div className="tournament-actions">
        {tournament.status === 'active' && !currentResult && (
          <button ref={startButton} type="button" className="control" onClick={props.startTurn}>
            Start turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 0 && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextTurn}>
            Next turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 1 && canAdvanceMatch && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextMatch}>
            Next match
          </button>
        )}
        {tournament.status === 'active' && (
          <button type="button" className="control" onClick={props.leave}>
            Leave tournament
          </button>
        )}
        {tournament.status === 'finished' && (
          <button ref={backButton} type="button" className="control" onClick={props.backToGame}>
            Back to game
          </button>
        )}
      </div>
      <TournamentBracket tournament={tournament} />
    </section>
  );
}

function GameStatistics({ game }: { game: NonNullable<TournamentState['activeGame']> }) {
  return (
    <dl className="stats tournament-stats">
      <div><dt>Moves:</dt> <dd>{game.moves}</dd></div>
      <div><dt>Pairs:</dt> <dd>{game.matched.length / 2}/{game.deck.length / 2}</dd></div>
      <div><dt>Time:</dt> <dd>{formatElapsed(game.elapsedMs)}</dd></div>
    </dl>
  );
}
import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { advanceTournamentGame } from '../tournament/rules.ts';
import type { TournamentState } from '../tournament/model.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import type { RefObject } from 'react';

export function useTournamentClock(
  state: TournamentState | null,
  current: RefObject<TournamentState | null>,
  commit: (next: TournamentState) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const started = state?.activeGame?.started ?? false;
  const won = state?.activeGame ? isWon(state.activeGame) : false;

  function running(): boolean {
    const latest = current.current;
    return visible.current && !!latest?.turnRunning && !!latest.activeGame?.started &&
      !isWon(latest.activeGame);
  }

  function synchronize(): void {
    const step = elapsedStep(clock.current, performance.now(), running());
    clock.current = step.clock;
    const latest = current.current;
    if (step.milliseconds && latest) commit(advanceTournamentGame(latest, step.milliseconds));
  }

  useEffect(() => {
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      const latest = current.current;
      if (!active || !latest?.turnRunning || !latest.activeGame?.started || !running()) return;
      const selection = latest.activeGame.selection;
      const delay = selection.kind === SelectionKind.mismatch
        ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
        : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize();
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active) return;
      synchronize();
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [state?.currentMatch, state?.currentTurn, state?.turnRunning, started, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
