import { isJsonObject, hasExactKeys, isWithinBytes, parseJson } from '../saved-format.ts';
import { encodeTournament } from './format.ts';
import { readTournamentRecord } from './validation.ts';
import type { TournamentRecord } from './model.ts';

const TOURNAMENTS_KEY = 'np3:tournaments';
const ENVELOPE_VERSION = 3;
const MAX_HISTORY = 10;
const MAX_STORAGE_BYTES = 1_048_576;

interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

interface TournamentHistory {
  readonly records: readonly TournamentRecord[];
  readonly available: boolean;
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistory {
  if (!store) return { records: [], available: false };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (!text) return { records: [], available: true };
    if (!isWithinBytes(text, MAX_STORAGE_BYTES)) return { records: [], available: true };
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      !hasExactKeys(value, ['items', 'v']) ||
      value.v !== ENVELOPE_VERSION ||
      !Array.isArray(value.items)
    ) return { records: [], available: true };
    const records = value.items.map(readTournamentRecord);
    return records.some((record) => !record)
      ? { records: [], available: true }
      : { records: records.filter((record): record is TournamentRecord => record !== null).slice(0, MAX_HISTORY), available: true };
  } catch {
    return { records: [], available: false };
  }
}

export function saveTournamentHistory(
  store: TournamentStore | null,
  record: TournamentRecord,
  previous: readonly TournamentRecord[],
): TournamentHistory {
  if (!store) return { records: [record, ...previous].slice(0, MAX_HISTORY), available: false };
  const identity = encodeTournament(record);
  const records = [record, ...previous.filter((item) => encodeTournament(item) !== identity)].slice(0, MAX_HISTORY);
  try {
    store.setItem(TOURNAMENTS_KEY, JSON.stringify({ v: ENVELOPE_VERSION, items: records }));
    return { records, available: true };
  } catch {
    return { records, available: false };
  }
}
import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame(foreground = true) {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit, foreground);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  function suspendForOtherScreen(): void {
    clock.synchronize();
    clock.reset();
  }

  function resumeFromOtherScreen(): void {
    clock.reset();
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    activate,
    resume,
    suspendForOtherScreen,
    resumeFromOtherScreen,
  };
}
