            onClick={() => leaveDialog.current?.close()}
          >
            Keep playing
          </button>
          <button
            type="button"
            className="control"
            onClick={() => {
              leaveDialog.current?.close();
              props.leave();
            }}
          >
            Leave tournament
          </button>
        </div>
      </dialog>
      <TournamentBracket tournament={tournament} />
    </section>
  );
}

  function updateName(index: number, name: string): void {
