    <section className="tournament-play" aria-labelledby="tournament-play-heading">
      <h3 id="tournament-play-heading">Tournament bracket</h3>
      {game && <GameStatistics game={game} />}
      {game && (tournament.turnRunning || isWon(game)) && (
        <>
          <p id="tournament-board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
          <button ref={startButton} type="button" className="control" onClick={props.startTurn}>
            Start turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 0 && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextTurn}>
            Next turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 1 && canAdvanceMatch && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextMatch}>
            Next match
          </button>
        )}
        {tournament.status === 'active' && (
          <button
            ref={leaveButton}
            type="button"
            className="control"
            onClick={() => setConfirmingLeave(true)}
          >
            Leave tournament
          </button>
        )}
        {tournament.status === 'finished' && (
          <button ref={backButton} type="button" className="control" onClick={props.backToGame}>
            Back to game
          </button>
        )}
      </div>
      <dialog
        ref={leaveDialog}
        className="tournament-confirmation"
        aria-labelledby="leave-tournament-heading"
        onClose={() => {
          setConfirmingLeave(false);
          leaveButton.current?.focus();
        }}
      >
        <h3 id="leave-tournament-heading">Leave this tournament?</h3>
        <p>Unfinished tournament progress will be discarded.</p>
        <div className="tournament-actions">
          <button
            ref={keepPlayingButton}
            type="button"
            className="control"
            onClick={() => leaveDialog.current?.close()}
          >
            Keep playing
          </button>
          <button
            type="button"
            className="control"
            onClick={() => {
              leaveDialog.current?.close();
              props.leave();
            }}
          >
            Leave tournament
          </button>
        </div>
      </dialog>
      <TournamentBracket tournament={tournament} />
    </section>
  );
}

  function updateName(index: number, name: string): void {
    setNames((previous) => previous.map((value, item) => item === index ? name : value));
  }

  function leave(): void {
    controller.discard();
    backToGame();
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={heading} tabIndex={-1}>Tournament</h2>
      <p className="intro">Take turns on the same deal. The player with fewer moves advances.</p>
      <div
        className={`game-result tournament-live-status ${tournament?.status === 'finished' ? 'tournament-live-champion' : ''}`}
      >
        <p id="tournament-status" role="status" aria-live="polite" aria-atomic="true">
          <span key={statusKey}>{statusText}</span>
        </p>
      </div>
      {controller.tournament ? (
        <TournamentPlay
          tournament={controller.tournament}
          activate={controller.activate}
          startTurn={controller.beginTurn}
          nextTurn={controller.continueTurn}
          nextMatch={controller.continueMatch}
          leave={leave}
          backToGame={backToGame}
        />
      ) : (
        <TournamentSetup
          count={count}
          names={names}
          notice={setupNotice}
      commit(loaded.state, false);
      const record = recordOf(loaded.state);
      if (record) archive(record);
    }
    return loaded;
  }

  function exportCurrent(count: number, names: readonly string[]): string {
    clock.synchronize();
    const source = current.current ?? historyRef.current[0];
    return source ? encodeTournament(source) : encodeTournamentSetup(count, names);
  }

  function viewPast(record: TournamentRecord): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    commit({ ...record, activeGame: null, turnRunning: false }, false);
  }

  function discard(): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    commit(null);
  }

  return {
    tournament,
    history,
    notice,
    feedback,
    announcement,
    storageAvailable,
    begin,
    beginTurn,
    activate,
    continueTurn,
    continueMatch,
    load,
    exportCurrent,
    viewPast,
    discard,
  };
}

