            reveals a card.
          </p>
          <Board
            key={`${tournament.currentMatch}-${tournament.currentTurn}`}
            ref={board}
            game={game}
            activate={props.activate}
            helpId="tournament-board-help"
            regionLabel="Tournament game board"
          />
        </>
      )}
      <div className="tournament-actions">
        {tournament.status === 'active' && !currentResult && (
          <button ref={startButton} type="button" className="control" onClick={props.startTurn}>
            Start turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 0 && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextTurn}>
            Next turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 1 && canAdvanceMatch && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextMatch}>
            Next match
          </button>
        )}
        {tournament.status === 'active' && (
          <button
            ref={leaveButton}
            type="button"
            className="control"
            onClick={() => {
              props.pauseClock();
              setConfirmingLeave(true);
            }}
          >
            Leave tournament
          </button>
        )}
        {tournament.status === 'finished' && (
          <button ref={backButton} type="button" className="control" onClick={props.backToGame}>
            Back to game
          </button>
        )}
      </div>
      <dialog
        ref={leaveDialog}
        className="tournament-confirmation"
        aria-labelledby="leave-tournament-heading"
        onClose={() => {
          setConfirmingLeave(false);
          props.resumeClock();
          leaveButton.current?.focus();
        }}
      >
        <h3 id="leave-tournament-heading">Leave this tournament?</h3>
        <p>Unfinished tournament progress will be discarded.</p>
        <div className="tournament-actions">
          <button
            ref={keepPlayingButton}
            type="button"
            className="control"
            onClick={() => leaveDialog.current?.close()}
          >
            Keep playing
          </button>
          <button
            type="button"
            className="control"
            onClick={() => {
              leaveDialog.current?.close();
              props.leave();
            }}
          >
            Leave tournament
          </button>
        </div>
      </dialog>
      <TournamentBracket tournament={tournament} />
    </section>
  );
}

