import { useEffect, useRef, useState } from 'react';
import { TournamentHistory } from './TournamentHistory.tsx';
import { TournamentPlay } from './TournamentPlay.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { playerName } from './model.ts';
import { TournamentTools } from './TournamentTools.tsx';
import { useTournament } from './use-tournament.ts';
import './tournament.css';

interface TournamentProps {
  backToGame(): void;
}

export function Tournament({ backToGame }: TournamentProps) {
  const controller = useTournament();
  const [count, setCount] = useState(4);
  const [names, setNames] = useState<string[]>(Array.from({ length: 8 }, () => ''));
  const [json, setJson] = useState('');
  const [setupNotice, setSetupNotice] = useState('');
  const [setupAnnouncement, setSetupAnnouncement] = useState(0);
  const heading = useRef<HTMLHeadingElement>(null);
  useEffect(() => heading.current?.focus(), []);

  const tournament = controller.tournament;
  const match = tournament?.matches[tournament.currentMatch];
  const player = tournament
    ? playerName(tournament, match?.playerSeeds[tournament.currentTurn] ?? null)
    : '';
  const currentResult = match?.results[tournament?.currentTurn ?? 0] ?? null;
  const turnStatus =
    tournament && match
      ? currentResult && tournament.currentTurn === 0
        ? `Turn complete: ${player}. Next up: ${playerName(tournament, match.playerSeeds[1])}`
        : currentResult
          ? `Match complete. Winner: ${playerName(tournament, match.winnerSeed)}`
          : `Now playing: ${player}`
      : '';
  const statusText =
    setupNotice ||
    (tournament?.status === 'finished'
      ? `Champion: ${playerName(tournament, tournament.championSeed)}${controller.feedback ? `. ${controller.feedback}` : ''}${controller.notice ? `. ${controller.notice}` : ''}`
      : `${turnStatus}${controller.feedback ? `. ${controller.feedback}` : ''}${controller.notice ? `. ${controller.notice}` : ''}`);
  const statusKey = `${controller.announcement}-${setupAnnouncement}-${tournament?.currentMatch ?? ''}-${tournament?.currentTurn ?? ''}-${tournament?.status ?? ''}`;

  function updateName(index: number, name: string): void {
    setNames((previous) => previous.map((value, item) => (item === index ? name : value)));
  }

  function leave(): void {
    controller.discard();
    backToGame();
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      <p className="intro">Take turns on the same deal. The player with fewer moves advances.</p>
      <div
        className={`game-result tournament-live-status ${tournament?.status === 'finished' ? 'tournament-live-champion' : ''}`}
      >
        <p id="tournament-status" role="status" aria-live="polite" aria-atomic="true">
          <span key={statusKey}>{statusText}</span>
        </p>
      </div>
      {controller.tournament ? (
        <TournamentPlay
          tournament={controller.tournament}
          activate={controller.activate}
          startTurn={controller.beginTurn}
          nextTurn={controller.continueTurn}
          nextMatch={controller.continueMatch}
          pauseClock={controller.pauseClock}
          resumeClock={controller.resumeClock}
          leave={leave}
          backToGame={backToGame}
        />
      ) : (
        <TournamentSetup
          count={count}
          names={names}
          notice={setupNotice}
          onCount={(value) => {
            setSetupNotice('');
            setCount(value);
          }}
          onName={(index, name) => {
            setSetupNotice('');
            updateName(index, name);
          }}
          onNotice={(message) => {
            setSetupNotice(message);
            setSetupAnnouncement((value) => value + 1);
          }}
          onStart={controller.begin}
          backToGame={backToGame}
        />
      )}
      <TournamentTools
        json={json}
        hasNotice={controller.notice !== ''}
        onJson={setJson}
        onExport={() => setJson(controller.exportCurrent(count, names))}
        onLoad={() => {
          setSetupNotice('');
          const loaded = controller.load(json);
          if (loaded?.kind === 'setup') {
            setCount(loaded.count);
            setNames([...loaded.names]);
          }
        }}
      />
      <TournamentHistory
        records={controller.history}
        storageAvailable={controller.storageAvailable}
        canView={controller.tournament?.status !== 'active'}
        onView={controller.viewPast}
      />
    </section>
  );
}
import { useEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { formatElapsed } from '../elapsed-time.ts';
import { isWon } from '../game.ts';
import type { TournamentState } from './model.ts';
import { TournamentBracket } from './TournamentBracket.tsx';
import './tournament.css';

interface TournamentPlayProps {
  tournament: TournamentState;
  activate(index: number): void;
  startTurn(): void;
  nextTurn(): void;
  nextMatch(): void;
  pauseClock(): void;
  resumeClock(): void;
  leave(): void;
  backToGame(): void;
}

export function TournamentPlay(props: TournamentPlayProps) {
  const { tournament } = props;
  const match = tournament.matches[tournament.currentMatch];
  const game = tournament.activeGame;
  const currentResult = match?.results[tournament.currentTurn] ?? null;
  const board = useRef<BoardFocus>(null);
  const startButton = useRef<HTMLButtonElement>(null);
  const nextButton = useRef<HTMLButtonElement>(null);
  const backButton = useRef<HTMLButtonElement>(null);
  const leaveButton = useRef<HTMLButtonElement>(null);
  const keepPlayingButton = useRef<HTMLButtonElement>(null);
  const leaveDialog = useRef<HTMLDialogElement>(null);
  const [confirmingLeave, setConfirmingLeave] = useState(false);
  const hasGame = game !== null;

  useEffect(() => {
    if (confirmingLeave && leaveDialog.current && !leaveDialog.current.open) {
      leaveDialog.current.showModal();
      keepPlayingButton.current?.focus();
    }
  }, [confirmingLeave]);

  useEffect(() => {
    if (tournament.status === 'finished') backButton.current?.focus();
    else if (currentResult) nextButton.current?.focus();
    else if (tournament.turnRunning && hasGame) board.current?.focusRemembered();
    else startButton.current?.focus();
  }, [
    tournament.currentMatch,
    tournament.currentTurn,
    tournament.turnRunning,
    hasGame,
    currentResult,
    tournament.status,
  ]);

  if (!match) return null;
  const canAdvanceMatch = tournament.currentMatch < tournament.matches.length - 1;
  return (
    <section className="tournament-play" aria-labelledby="tournament-play-heading">
      <h3 id="tournament-play-heading">Tournament bracket</h3>
      {game && <GameStatistics game={game} />}
      {game && (tournament.turnRunning || isWon(game)) && (
        <>
          <p id="tournament-board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board
            key={`${tournament.currentMatch}-${tournament.currentTurn}`}
            ref={board}
            game={game}
            activate={props.activate}
            helpId="tournament-board-help"
            regionLabel="Tournament game board"
          />
        </>
      )}
      <div className="tournament-actions">
        {tournament.status === 'active' && !currentResult && (
          <button ref={startButton} type="button" className="control" onClick={props.startTurn}>
            Start turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 0 && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextTurn}>
            Next turn
          </button>
        )}
        {tournament.status === 'active' &&
