import { useTournament } from './use-tournament.ts';
import './tournament.css';

interface TournamentProps {
  backToGame(): void;
}

export function Tournament({ backToGame }: TournamentProps) {
  const controller = useTournament();
  const [count, setCount] = useState(4);
  const [names, setNames] = useState<string[]>(Array.from({ length: 8 }, () => ''));
  const [json, setJson] = useState('');
  const [setupNotice, setSetupNotice] = useState('');
  const [setupAnnouncement, setSetupAnnouncement] = useState(0);
  const [confirmation, setConfirmation] = useState<'leave' | 'load' | null>(null);
  const [pendingLoad, setPendingLoad] = useState('');
  const heading = useRef<HTMLHeadingElement>(null);
  useEffect(() => heading.current?.focus(), []);

  const tournament = controller.tournament;
  const match = tournament?.matches[tournament.currentMatch];
  const player = tournament
    ? playerName(tournament, match?.playerSeeds[tournament.currentTurn] ?? null)
    : '';
  const currentResult = match?.results[tournament?.currentTurn ?? 0] ?? null;
  const turnStatus =
    tournament && match
      ? currentResult && tournament.currentTurn === 0
        ? `Turn complete: ${player}. Next up: ${playerName(tournament, match.playerSeeds[1])}`
        : currentResult
          ? `Match complete. Winner: ${playerName(tournament, match.winnerSeed)}`
          : `Now playing: ${player}`
      : '';
  const statusText =
    setupNotice ||
    (tournament?.status === 'finished'
      ? `Champion: ${playerName(tournament, tournament.championSeed)}${controller.feedback ? `. ${controller.feedback}` : ''}${controller.notice ? `. ${controller.notice}` : ''}`
      : `${turnStatus}${controller.feedback ? `. ${controller.feedback}` : ''}${controller.notice ? `. ${controller.notice}` : ''}`);
  const statusKey = `${controller.announcement}-${setupAnnouncement}-${tournament?.currentMatch ?? ''}-${tournament?.currentTurn ?? ''}-${tournament?.status ?? ''}`;

  function updateName(index: number, name: string): void {
    setNames((previous) => previous.map((value, item) => (item === index ? name : value)));
  }

  function applyLoad(text: string): void {
    setSetupNotice('');
    const loaded = controller.load(text);
    if (loaded?.kind === 'setup') {
      setCount(loaded.count);
      setNames([...loaded.names]);
    }
  }

  function requestLeave(): void {
    controller.pauseClock();
    setConfirmation('leave');
  }

  function requestLoad(): void {
    if (!decodeTournament(json)) {
      applyLoad(json);
      return;
    }
    if (controller.tournament?.status === 'active') {
      controller.pauseClock();
      setPendingLoad(json);
      setConfirmation('load');
      return;
    }
    applyLoad(json);
  }

  function confirmAction(): void {
    if (confirmation === 'leave') {
      controller.discard();
      backToGame();
    } else if (confirmation === 'load' && pendingLoad) {
      controller.resumeClock();
      applyLoad(pendingLoad);
      setPendingLoad('');
    }
  }

  function closeConfirmation(): void {
    setConfirmation(null);
    setPendingLoad('');
    controller.resumeClock();
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      <p className="intro">Take turns on the same deal. The player with fewer moves advances.</p>
      <div
        className={`game-result tournament-live-status ${tournament?.status === 'finished' ? 'tournament-live-champion' : ''}`}
      >
        <p id="tournament-status" role="status" aria-live="polite" aria-atomic="true">
          <span key={statusKey}>
            {tournament?.status === 'active' && match && (
              <>
                Round: {match.round}
                <br />
              </>
            )}
            {statusText}
          </span>
        </p>
      </div>
      {controller.tournament ? (
        <TournamentPlay
          tournament={controller.tournament}
          activate={controller.activate}
          startTurn={controller.beginTurn}
          nextTurn={controller.continueTurn}
          nextMatch={controller.continueMatch}
          leave={requestLeave}
          backToGame={backToGame}
        />
      ) : (
        <TournamentSetup
          count={count}
          names={names}
          notice={setupNotice}
          onCount={(value) => {
            setSetupNotice('');
            setCount(value);
          }}
          onName={(index, name) => {
            setSetupNotice('');
            updateName(index, name);
          }}
          onNotice={(message) => {
            setSetupNotice(message);
            setSetupAnnouncement((value) => value + 1);
          }}
          onStart={controller.begin}
          backToGame={backToGame}
        />
      )}
      <TournamentTools
        json={json}
        hasNotice={controller.notice !== ''}
        onJson={setJson}
        onExport={() => setJson(controller.exportCurrent(count, names))}
        onLoad={requestLoad}
      />
      <TournamentHistory
        records={controller.history}
        storageAvailable={controller.storageAvailable}
      />
      <TournamentConfirmation
        action={confirmation}
        onClose={closeConfirmation}
        onConfirm={confirmAction}
      />
    </section>
  );
}
import { useRef, useState } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { browserStore } from '../session/use-saved-preferences.ts';
import { useTournamentClock } from '../session/use-tournament-clock.ts';
import { matchSpecs } from './bracket.ts';
import { decodeTournament, encodeTournament, encodeTournamentSetup } from './format.ts';
import { acceptedNames, recordOf } from './model.ts';
import type { TournamentImport, TournamentRecord, TournamentState } from './model.ts';
import {
  createTournament,
  activateTournamentCard,
  nextMatch,
  nextTurn,
  startTurn,
} from './rules.ts';
import { readTournamentHistory, saveTournamentHistory } from './storage.ts';
import { findUnknownTournamentField } from './validation.ts';

export function useTournament() {
  const [store] = useState(browserStore);
  const [initial] = useState(() => readTournamentHistory(store));
  const [history, setHistory] = useState<readonly TournamentRecord[]>(initial.records);
  const historyRef = useRef(initial.records);
  const [storageAvailable, setStorageAvailable] = useState(initial.available);
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const current = useRef<TournamentState | null>(null);
  const [notice, setNotice] = useState('');
  const [feedback, setFeedback] = useState('');
  const [announcement, setAnnouncement] = useState(0);
  const clock = useTournamentClock(tournament, current, commit);

  function archive(record: TournamentRecord): void {
    const saved = saveTournamentHistory(store, record, historyRef.current);
    historyRef.current = saved.records;
    setHistory(saved.records);
    setStorageAvailable(saved.available);
  }

  function commit(next: TournamentState | null, saveFinished = true): void {
    const previous = current.current;
    if (next === previous) return;
    current.current = next;
    setTournament(next);
    if (
      saveFinished &&
      next?.championSeed !== null &&
      next?.championSeed !== undefined &&
      previous?.championSeed === null
    ) {
      const record = recordOf(next);
      if (record) archive(record);
    }
  }

  function begin(names: readonly string[]): boolean {
    const players = acceptedNames(names, names.length);
    if (!players || (players.length !== 4 && players.length !== 8)) return false;
    const specs = matchSpecs(players.length);
    const used = new Set<string>();
    const codes = specs.map((spec) => {
      let code = freshBoardCode(spec.size);
      while (used.has(code)) code = freshBoardCode(spec.size);
      used.add(code);
      return code;
    });
    clock.reset();
    setNotice('');
    setFeedback('');
    commit(createTournament(players, specs, codes));
    return true;
  }

  function beginTurn(): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    const latest = current.current;
    if (latest) commit(startTurn(latest));
  }

  function activate(index: number): void {
    clock.synchronize();
    const latest = current.current;
    if (!latest) return;
    const next = activateTournamentCard(latest, index);
    const game = next.activeGame;
    if (next !== latest && game && game.selection.kind !== SelectionKind.one) {
      setNotice('');
      const result = isWon(game)
        ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
        : game.selection.kind === SelectionKind.mismatch
          ? 'No match. Cards close after a short pause.'
          : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
      setFeedback(result);
      setAnnouncement((value) => value + 1);
    }
    commit(next);
  }

  function continueTurn(): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    const latest = current.current;
    if (latest) commit(nextTurn(latest));
  }

  function continueMatch(): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    const latest = current.current;
    if (latest) commit(nextMatch(latest));
  }

  function load(text: string): TournamentImport | null {
    const loaded = decodeTournament(text);
    if (!loaded) {
      const field = findUnknownTournamentField(text);
      setNotice(field ? `Unknown field: ${field}.` : 'Invalid tournament.');
      setAnnouncement((value) => value + 1);
      return null;
    }
    clock.reset();
    setFeedback('');
    if (loaded.kind === 'setup') {
      setNotice('Loaded tournament setup.');
      setAnnouncement((value) => value + 1);
      commit(null);
    } else {
      setNotice('Loaded tournament.');
      setAnnouncement((value) => value + 1);
      commit(loaded.state, false);
      const record = recordOf(loaded.state);
      if (record) archive(record);
    }
    return loaded;
  }

  function exportCurrent(count: number, names: readonly string[]): string {
    clock.synchronize();
    const source = current.current;
    return source ? encodeTournament(source) : encodeTournamentSetup(count, names);
  }

  function discard(): void {
    clock.reset();
    setNotice('');
    setFeedback('');
    commit(null);
  }

  return {
    tournament,
    history,
    notice,
    feedback,
    announcement,
    storageAvailable,
    begin,
    beginTurn,
    activate,
    continueTurn,
    continueMatch,
    pauseClock: clock.pause,
    resumeClock: clock.resume,
    load,
    exportCurrent,
    discard,
  };
}

import { useEffect, useRef, useState } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { advanceTournamentGame } from '../tournament/rules.ts';
import type { TournamentState } from '../tournament/model.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import type { RefObject } from 'react';

export function useTournamentClock(
  state: TournamentState | null,
  current: RefObject<TournamentState | null>,
  commit: (next: TournamentState) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const suspended = useRef(false);
  const [isSuspended, setIsSuspended] = useState(false);
  const started = state?.activeGame?.started ?? false;
  const won = state?.activeGame ? isWon(state.activeGame) : false;

  function running(): boolean {
    const latest = current.current;
    return (
      visible.current &&
      !suspended.current &&
      !!latest?.turnRunning &&
      !!latest.activeGame?.started &&
      !isWon(latest.activeGame)
    );
  }

  function synchronize(): void {
    const step = elapsedStep(clock.current, performance.now(), running());
    clock.current = step.clock;
    const latest = current.current;
    if (step.milliseconds && latest) commit(advanceTournamentGame(latest, step.milliseconds));
  }

  useEffect(() => {
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      const latest = current.current;
      if (!active || !latest?.turnRunning || !latest.activeGame?.started || !running()) return;
      const selection = latest.activeGame.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize();
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active) return;
      synchronize();
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [state?.currentMatch, state?.currentTurn, state?.turnRunning, started, won, isSuspended]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
    pause: () => {
      synchronize();
      suspended.current = true;
      clock.current = createClock(performance.now());
      setIsSuspended(true);
    },
    resume: () => {
      clock.current = createClock(performance.now());
      suspended.current = false;
      setIsSuspended(false);
    },
  };
}
import { useEffect, useRef, useState } from 'react';
