import type { FormEvent } from 'react';
import { acceptedNames, normalizePlayerName } from './model.ts';
import './tournament.css';

interface SetupProps {
  count: number;
  names: readonly string[];
  onCount(count: number): void;
  onName(index: number, name: string): void;
  notice: string;
  onNotice(message: string): void;
  onStart(names: readonly string[]): void;
  backToGame(): void;
}

export function TournamentSetup({
  count,
  names,
  notice,
  onCount,
  onName,
  onNotice,
  onStart,
  backToGame,
}: SetupProps) {
  function submit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const chosen = names.slice(0, count).map(normalizePlayerName);
    if (chosen.some((name) => Array.from(name).length < 2 || Array.from(name).length > 20)) {
      onNotice('Use 2 to 20 characters.');
      return;
    }
    if (new Set(chosen.map((name) => name.toLowerCase())).size !== count) {
      onNotice('Each name must be different.');
      return;
    }
    const accepted = acceptedNames(names, count);
    if (!accepted) return;
    onNotice('');
    onStart(accepted);
  }
  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-heading">
      <h3 id="tournament-setup-heading">Set up tournament</h3>
      <form onSubmit={submit}>
        <div className="tournament-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={count}
            onChange={(event) => onCount(Number(event.currentTarget.value))}
          >
            <option value={4}>4</option>
            <option value={8}>8</option>
          </select>
        </div>
        <div className="tournament-players">
          {Array.from({ length: 8 }, (_, index) => (
            <div className="tournament-player-field" key={index}>
              <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
              <input
                id={`tournament-player-${index + 1}`}
                className="control"
                type="text"
                autoComplete="off"
                aria-describedby={notice ? 'tournament-status' : undefined}
                value={names[index] ?? ''}
                disabled={index >= count}
                onChange={(event) => onName(index, event.currentTarget.value)}
              />
            </div>
          ))}
        </div>
        <div className="tournament-actions">
          <button type="submit" className="control">
            Start tournament
          </button>
          <button type="button" className="control" onClick={backToGame}>
            Back to game
          </button>
        </div>
      </form>
    </section>
  );
}
import { formatElapsed } from '../elapsed-time.ts';
import { playerName } from './model.ts';
import type { TournamentMatch, TournamentState } from './model.ts';
import './tournament.css';

interface BracketProps {
  tournament: Pick<TournamentState, 'players' | 'matches' | 'currentMatch'>;
}

export function TournamentBracket({ tournament }: BracketProps) {
  return (
    <section className="tournament-bracket" aria-labelledby="tournament-bracket-heading">
      <h3 id="tournament-bracket-heading">Bracket</h3>
      {tournament.matches.map((match, index) => (
        <MatchTable
          key={`${match.round}-${match.matchNumber}`}
          match={match}
          index={index}
          tournament={tournament}
        />
      ))}
    </section>
  );
}

function MatchTable({
  match,
  index,
  tournament,
}: {
  match: TournamentMatch;
  index: number;
  tournament: BracketProps['tournament'];
}) {
  return (
    <table className="tournament-match">
      <caption>
        {match.round} {match.matchNumber}
        {index === tournament.currentMatch ? ' — Current match' : ''}
      </caption>
      <thead>
        <tr>
          <th scope="col">Player</th>
          <th scope="col">Moves</th>
          <th scope="col">Time</th>
          <th scope="col">Winner</th>
        </tr>
      </thead>
      <tbody>
        {match.playerSeeds.map((seed, turn) => {
          const result = turn === 0 ? match.results[0] : match.results[1];
          const name = playerName(tournament, seed);
          return (
            <tr key={`${match.matchNumber}-${turn}`}>
              <th scope="row">{seed === null ? name : `${seed}. ${name}`}</th>
              <td>{result?.moves ?? '—'}</td>
              <td>{result ? formatElapsed(result.elapsedMs) : '—'}</td>
              <td>{seed !== null && seed === match.winnerSeed ? 'Winner' : '—'}</td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

import { playerName } from './model.ts';
import type { TournamentRecord } from './model.ts';
import './tournament.css';

interface HistoryProps {
  records: readonly TournamentRecord[];
  storageAvailable: boolean;
}

export function TournamentHistory({ records, storageAvailable }: HistoryProps) {
  return (
    <section className="tournament-history" aria-labelledby="past-tournaments-heading">
      <h3 id="past-tournaments-heading">Past tournaments</h3>
      {!storageAvailable && <p>Progress won&apos;t be saved on this device.</p>}
      {records.length === 0 ? (
        <p>No past tournaments yet.</p>
      ) : (
        <table>
          <caption>Finished tournaments</caption>
          <thead>
            <tr>
              <th scope="col">Players</th>
              <th scope="col">Champion</th>
              <th scope="col">Matches</th>
            </tr>
          </thead>
          <tbody>
            {records.map((record, index) => {
              const champion = playerName(record, record.championSeed);
              const names = record.players.map((player) => player.name).join(', ');
              return (
                <tr key={`${record.championSeed}-${index}`}>
                  <td>{names}</td>
                  <td>{champion}</td>
                  <td>{record.matches.length}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </section>
  );
}
